\label{de:b}\label{de:cc} Let $(A, [, ])$ be a left Alia algebra. A {\bf representation} of $(A, [, ])$ is a triple $(V, \ell, r)$, where $V$ is a vector space and $\ell, r: A\longrightarrow \mathrm{End}(V)$ are linear maps such that the following equation holds:
 \begin{eqnarray}
 \ell([x, y])-\ell([y, x])=r(x)(r(y)-\ell(y))-r(y)(r(x)-\ell(x)), \forall~ x, y\in A.\label{eq:2}
 \end{eqnarray}
 Let $(V_{A}, \ell_{A}, r_{A})$ and $(V_{B}, \ell_{B}, r_{B})$ be representations of $(A, [,]_{A})$ and $(B, [,]_{B})$ respectively. Then $(\phi, f)$ is a {\bf homomorphism from $(V_{A}, \ell_{A}, r_{A})$ of $(A, [,]_{A})$ to $(V_{B}, \ell_{B}, r_{B})$ of $(B, [,]_{B})$} if there are linear maps $\phi: V_{A}\longrightarrow V_{B}$ and $f: A\longrightarrow B$ such that $f([x, y]_{A})=[f(x), f(y)]_{B}$ and
 \begin{eqnarray} 
 &\phi(\ell_{A}(x)(v))=\ell_{B}(f(x))(\phi(v)), ~~~ \phi(r_{A}(x)(v))=r_{B}(f(x))(\phi(v)), &\label{eq:cc1}	
 \end{eqnarray}
 where $x, y\in A, v\in V$.

\label{pro:c} Let $(A, [, ])$ be a left Alia algebra, $V$ be a vector space and $\ell, r: A\longrightarrow \mathrm{End}(V)$ be linear maps. Then $(V, \ell, r)$ is a representation of $(A, [, ])$ if and only if there is a left Alia algebra $(A\oplus V,  [, ]_{A\oplus V})$ on the direct sum $A\oplus V$ of vector spaces, where $[, ]_{A\oplus V}$ is given by
 \begin{eqnarray}
 &[x+u, y+v]_{A\oplus V}:=[x, y]+\ell(x)v+r(y)u, \forall~ x, y\in A, u, v\in V. &\label{eq:3}
 \end{eqnarray}
 We denote this left Alia algebra by $A\ltimes_{\ell, r} V$ and call it {\bf semi-direct product of $(A, [,])$ by $(V, \ell, r)$}.

\label{ex:d} Let $(A, [, ])$ be a left Alia algebra. Define linear maps $\mathcal{L}, \mathcal{R}: A\longrightarrow \mathrm{End}(A)$ by
 \begin{eqnarray}
 &\mathcal{L}(x)y=[x, y]=\mathcal{R}(y)x, \forall~ x, y \in A. &\label{eq:4}
 \end{eqnarray}
 Then $(A, \mathcal{L}, \mathcal{R})$ is a representation of $(A, [, ])$, which is called an {\bf adjoint representation}.

\label{thm:fff} Assume that $(A, [, ]_{\circ})$, $\ell$ and $r$ are defined in Lemma \ref{lem:ff}, $(V, \ell, r)$ is a representation of $(A, [, ]_{\circ})$, $(V, \ell_{1}, r_{1})$ is a representation of $(A, [, ])$. Let $N\in \mathrm{End}(A)$ and $\alpha\in \mathrm{End}(V)$ be two linear maps. Then $(s \id_{A}+tN, sid_{V}+t\alpha)$ is a homomorphism from $(V, \ell, r)$ of $(A, [, ]_{\circ})$ to $(V, \ell_{1}, r_{1})$ of $(A, [, ])$ if and only if, for all $x, y\in A$ and $v\in V$,
 \begin{eqnarray}
 &[x, y]_{\cdot}=[N(x), y]+[x, N(y)]-N([x, y]),&\label{eq:nn1}\\
 &N([x, y]_{\cdot})=[N(x), N(y)],&\label{eq:nn2}\\
 &\ell_{2}(x)(v)=\ell_{1}(N(x))(v)+\ell_{1}(x)(\alpha(v))-\alpha(\ell_{1}(x)(v)),&\label{eq:nn3}\\
 &\alpha(\ell_{2}(x)(v))=\ell_{1}(N(x))(\alpha(v)),&\label{eq:nn4}\\
 &r_{2}(x)(v)=r_{1}(N(x))(v)+r_{1}(x)(\alpha(v))-\alpha(r_{1}(x)(v)),&\label{eq:nn5}\\
 &\alpha(r_{2}(x)(v))=r_{1}(N(x))(\alpha(v)).&\label{eq:nn6}
 \end{eqnarray}

\label{de:l} Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra. A {\bf representation} of $((A, [, ]), N)$ is a pair $((V, \ell, r), \alpha)$, where $(V, \ell, r)$ is a representation of $(A, [, ])$ and $\alpha: V\longrightarrow V$ is a linear map such that, for all $x\in A, v\in V$, the following equations hold:
 \begin{eqnarray}
 &\ell(N(x))(\alpha(v))+\alpha^{2}(\ell(x)(v))=\alpha(\ell(N(x))(v))+\alpha(\ell(x)(\alpha(v))),\label{eq:8}\\
 &r(N(x))(\alpha(v))+\alpha^{2}(r(x)(v))=\alpha(r(N(x))(v))+\alpha(r(x)(\alpha(v))).\label{eq:9}
 \end{eqnarray}

 Let $((V_{1}, \ell_{1}, r_{1}), \alpha_{1})$ and $((V_{2}, \ell_{2}, r_{2}), \alpha_{2})$ be representations of $((A, [, ]), N)$. A linear map $\phi: V_{1}\longrightarrow V_{2}$ is called a {\bf homomorphism from $((V_{1}, \ell_{1}, r_{1}), \alpha_{1})$ to $((V_{2}, \ell_{2}, r_{2}), \alpha_{2})$} if $(\phi, \id_A)$ is a homomorphism from $(V_{1}, \ell_{1}, r_{1})$ to $(V_{2}, \ell_{2}, r_{2})$ and, for all $v\in V_{1}$,
 \begin{eqnarray}\label{eq:10}
 \phi(\alpha_{1}(v))=\alpha_{2}(\phi(v)).
 \end{eqnarray}
 If $\phi$ is a bijective, then we say that the representations $((V_{1}, \ell_{1}, r_{1}), \alpha_{1})$ and $((V_{2}, \ell_{2}, r_{2}), \alpha_{2})$ are {\bf equivalent}.

\label{ex:m}
 \begin{enumerate}[(1)]
 \item Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra. Then $((A, \mathcal{L}, \mathcal{R}), N)$ a representation of $((A, [, ]), N)$, called the {\bf adjoint representation} of $((A, [, ]), N)$.  
 	
 \item Let $((V, \rho), \alpha)$ be a representation of a Nijenhuis Lie algebra $((A, [, ]), N)$ \cite{LM}, then, both $((V, \rho, -\rho), \alpha)$ and $((V, \rho, 2\rho), \alpha)$ are representation of $((A, [, ]), N)$ as a Nijenhuis left Alia algebra.
 \end{enumerate}

\label{pro:n} Let $((V, \ell, r), \alpha)$ be a representation of a Nijenhuis left Alia algebra $((A, [, ]), N)$. Define the bracket product on $A\oplus V$ by Eq. $\eqref{eq:3}$, and a linear map $N+\alpha: A\oplus V\longrightarrow A\oplus V$ by
 \begin{eqnarray}
 (N+\alpha)(x+v):=N(x)+\alpha(v), \forall~ x\in A, \forall~ v\in V.\label{eq:11}
 \end{eqnarray}
 Then $((A\oplus V, [, ]_{A\oplus V}), N+\alpha)$ is a Nijenhuis left Alia algebra denoted by $(A\ltimes_{\ell, r}V,  N+\alpha)$ and called {\bf semi-direct product of $((A, [,]), N)$ by $((V, \ell, r), \alpha)$}.

\label{lem:o} Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra, $(V, \ell, r)$ a representation of $(A, [, ])$ and $\beta: V\longrightarrow V$ a linear map. Then $((V^{*}, \ell^{*}, \ell^{*}-r^{*}), \beta^{*})$ is a representation of $((A, [, ]), N)$ if and only if, for all $x\in A$, $v\in V$,
 \begin{eqnarray}
 &\beta(\ell(N(x))(v))+\ell(x)(\beta^{2}(v))=\ell(N(x))(\beta(v))+\beta(\ell(x)(\beta(v))),&\label{eq:13}\\
 &\beta(r(N(x))(v))+r(x)(\beta^{2}(v))=r(N(x))(\beta(v))+\beta(r(x)(\beta(v))).\label{eq:14}
 \end{eqnarray}
 In particular, for a linear map $S: A\longrightarrow A$, $((A^{*}, \mathcal{L}^{*}, \mathcal{L}^{*}-\mathcal{R}^{*}), S^{*})$ is a representation of $((A, [, ]), N)$ if and only if, for all $x,y\in A$,
 \begin{eqnarray}
 &S[N(x), y]+[x, S^{2}(y)]=S[x, S(y)]+[N(x), S(y)],&\label{eq:15}\\
 &S[x, N(y)]+[S^{2}(x), y]=S[S(x), y]+[ S(x), N(y)].&\label{eq:16}
 \end{eqnarray}

\label{pro:al}{\em \cite{KLWY}} Let $(A, [, ]_{A})$ and $(B, [, ]_{B})$ be left Alia algebras, $\ell_{A}, r_{A}: A\longrightarrow \mathrm{End}(B)$ and $\ell_{B}, r_{B}: B\longrightarrow \mathrm{End}(A)$ be linear maps. Define the bracket $[, ]_{A\oplus B}$ on the direct sum $A\oplus B$ of vector spaces given by
 \begin{eqnarray}\label{eq:sum}
 [x+a, y+b]_{A\oplus B}:=[x, y]_{A}+\ell_{B}(a)(y)+r_{B}(b)(x)+[a, b]_{B}+\ell_{A}(x)(b)+r_{A}(y)(a),
 \end{eqnarray}
 where $x, y\in A$ and $a, b\in B$, then $(A\oplus B, [, ]_{A\oplus B})$ is a left Alia algebra if and only if  $((A, [, ]_{A}), (B, [, ]_{B}), \ell_{A}, r_{A}, \ell_{B}, r_{B})$ is a matched pair of left Alia algebras, that is, $(B, \ell_{A}, r_{A})$ is a representation of $(A, [, ]_{A})$, $(A, \ell_{B}, r_{B})$ is a representation of $(B, [, ]_{B})$, and the following equations hold:
 \begin{eqnarray*}
 r_{B}(a)([x, y]_{A}-[y, x]_{A})
 \hspace{-3mm}&=&\hspace{-3mm}[(\ell_{B}-r_{B})(a)(y), x]_{A}+[(r_{B}-\ell_{B})(a)(x), y]_{A}\\
 &&\hspace{-3mm}+\ell_{B}((r_{A}-\ell_{A})(y)(a))(x)+\ell_{B}((\ell_{A}-r_{A})(x)(a))(y),\\
 r_{A}(x)([a, b]_{B}-[b, a]_{B})
 \hspace{-3mm}&=&\hspace{-3mm}[(\ell_{A}-r_{A})(x)(b), a]_{B}+[(r_{A}-\ell_{A})(x)(a), b]_{B}\\
 &&\hspace{-3mm}+\ell_{A}((r_{B}-\ell_{B})(b)(x))(a)+\ell_{A}((\ell_{B}-r_{B})(a)(x))(b).
 \end{eqnarray*}

\label{thm:an} Let $((A, [, ]_{A}), N_{A})$ and $((B, [, ]_{B}), N_{B})$ be Nijenhuis left Alia algebras. Then $((A, N_{A}), (B, N_{B}), \ell_{A}, r_{A}, \ell_{B}, r_{B})$ is a matched pair of $((A, [, ]_{A}), N_{A})$ and $((B, [, ]_{B}), N_{B})$ if and only if $((A\oplus B, [,]_{A\oplus B}), N_{A}+N_{B})$ is a Nijenhuis left Alia algebra by defining the multiplication on $A\oplus B$ by Eq.\eqref{eq:sum} and linear map $N_{A}+N_{B}: A\oplus B\longrightarrow A\oplus B$ by
 \begin{eqnarray}
 (N_{A}+N_{B})(x+a):=N_{A}(x)+N_{B}(a)\label{eq:avnj}
 \end{eqnarray}
 for all $x\in A$, $a\in B$.

\label{pro:ao} Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra and $(A, [, ], \mathcal{B})$ a quadratic left Alia algebra. Assume that $\widehat{N}$ is the adjoint linear map of $N$ with respect to $\mathcal{B}$, characterized by
 \begin{eqnarray}\label{adjoint B}
 \mathcal{B}(N(x), y)=\mathcal{B}(x, \widehat{N}(y)), \forall~ x, y\in A.
 \end{eqnarray}
 Then $\widehat{N}$ is adjoint-admissible to~ $((A, [, ]), N)$, or equivalently, $((A^{*}, \mathcal{L}^{*}, \mathcal{L}^{*}-\mathcal{R}^{*}), \widehat{N}^{*})$ is a representation of $((A, [, ]), N)$. Moreover, $((A^{*}, \mathcal{L}^{*}, \mathcal{L}^{*}-\mathcal{R}^{*}), \widehat{N}^{*})$ is equivalent to $((A, \mathcal{L}, \mathcal{R}), N)$ as representations of $((A, [, ]), N)$. Conversely, Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra and $S: A\longrightarrow A$ a linear map that is adjoint-admissible to~ $((A, [,]), N)$. If the resulting representation $((A^{*}, \mathcal{L}^{*}, \mathcal{L}^{*}-\mathcal{R}^{*}), S^{*})$ of $((A, [, ]), N)$ is equivalent to $((A, \mathcal{L}, \mathcal{R}), N)$, then there exists a quadratic left Alia  algebra $(A, [, ], \mathcal{B})$ such that $S=\widehat{N}$.

\label{eq:ap}\cite{KLWY} Let $(A, [, ]_{A})$ and $(A^{*}, [, ]_{A^{*}})$ be two left Alia algebras. Assume that there is a left Alia algebras $(A\oplus A^{*}, [, ]_{A\oplus A^{*}})$ which contains $(A, [, ]_{A})$ and $(A^{*}, [, ]_{A^{*}})$ as left Alia subalgebras. Suppose that the natural nondegenerate symmetric bilinear form $\mathcal{B}$, given by
 \begin{eqnarray}\label{eq:naturalb}
 \mathcal{B}(x+a^{*}, y+b^{*})=\langle a^{*}, y\rangle+\langle x, b^{*}\rangle, \forall~ x, y\in A,  a^{*}, b^{*}\in A^{*},
 \end{eqnarray} 	
 is invariant on $(A\oplus A^{*}, [, ]_{A\oplus A^{*}})$, that is, $(A\oplus A^{*}, [, ]_{A\oplus A^{*}}, \mathcal{B})$ is a quadratic left Alia algebra. Then, we say that $((A\oplus A^{*}, [, ]_{A\oplus A^{*}}, \mathcal{B}), A, A^{*})$ is a {\bf Manin triple of left Alia algebras associated to $(A, [, ]_{A})$ and $(A^{*}, [, ]_{A^{*}})$}.

\label{de:ah} 	A {\bf Nijenhuis left Alia coalgebra} is a pair $((A, \Delta), S)$, where $(A, \Delta)$ is a left Alia coalgebra and $S$ is a Nijenhuis operator on $(A, \Delta)$, i.e., the following identity holds:
 \small{\begin{eqnarray}\label{eq:nlaca}
 S(x_{(1)})\otimes S(x_{(2)})+S^{2}(x)_{(1)}\otimes S^{2}(x)_{(2)}=S(S(x)_{(1)})\otimes S(x)_{(2)}+S(x)_{(1)}\otimes S(S(x)_{(2)}), \forall~ x\in A.
 \end{eqnarray}}

\label{ex:auu}
 Let $(A, [, ])$ be a 4-dimensional left Alia algebra with basis ${e_{1}, e_{2}, e_{3}, e_{4}}$ and the product $[, ]$ given by the following table
 \begin{center}
 \begin{tabular}{r|rrrr}
 $[,]$ & $e_{1}$  & $e_{2}$ & $e_{3}$ & $e_{4}$\\
 \hline
 $e_{1}$ & $0$  & $0$ & $0$ & $0$\\
 $e_{2}$ & $0$  & $0$ & $0$  & $0$\\
 $e_{3}$ & $e_{1}$  & $0$ & $0$ & $0$\\
 $e_{4}$ & $e_{3}$  & $0$ & $0$ & $0$\\
 \end{tabular}.
 \end{center}
 Define
 \begin{center}
 $\begin{cases}
 N(e_{1})=e_{1}\\
 N(e_{2})=e_{1}+e_{2}\\
 N(e_{3})=e_{3}\\
 N(e_{4})=e_{4}\\
 \end{cases}$.
 \end{center}
 Then $((A, [, ]), N)$ is a Nijenhuis left Alia algebra. Set
 \begin{center}
 $\begin{cases}
 \Delta_{r}(e_{1})=0\\
 \Delta_{r}(e_{2})=0\\
 \Delta_{r}(e_{3})=-e_{1}\otimes e_{2}\\
 \Delta_{r}(e_{4})=-e_{3}\otimes e_{2}\\
 \end{cases}$
 \end{center}
 and
 \begin{center}
 $\begin{cases}
 S(e_{1})=e_{1}\\
 S(e_{2})=e_{2}-e_{1}\\
 S(e_{3})=e_{3}\\
 S(e_{4})=e_{4}-e_{1}\\
 \end{cases}$
 \end{center}
 Then $((A,\Delta), S)$ is a Nijenhuis left Alia coalgebra. Furthermore, $((A, [, ], \Delta), N, S)$ is a Nijenhuis left Alia bialgebra.

\label{de:u}\cite{KLY}~Let $(A, [, ])$ be a left Alia algebra and $r=\sum_{i} a_{i}\otimes b_{i}\in A\otimes A$. We call
 \begin{eqnarray}
 Al(r)=\sum_{i, j}\Big([a_{i}, a_{j}]\otimes b_{i}\otimes b_{j}+a_{i}\otimes ([a_{j}, b_{i}]-[b_{i}, a_{j}])\otimes b_{j}-a_{i}\otimes a_{j}\otimes [b_{j}, b_{i}]\Big)=0.\label{eq:ybq}
 \end{eqnarray}
 a {\bf left Alia Yang-Baxter equation in $(A, [, ])$}. And in this case we say $r$ is a {\bf solution of the left Alia Yang-Baxter equation in $(A, [, ])$}.

\label{de:v}\cite{KLY} Let $(A, [, ])$ be a left Alia algebra and $r=\sum_{i} a_{i}\otimes b_{i}\in A\otimes A$. Suppose that $r$ is an antisymmetric solution of the left Alia Yang-Baxter equation. Then $(A, [, ], \Delta_{r})$ is a left Alia bialgebra, where $\Delta_{r}: A\longrightarrow A\otimes A$ is given by
 \begin{eqnarray}
 \Delta_{r}(x)=\sum_{i}\big(([a_{i}, x]-[x, a_{i}])\otimes b_{i}-a_{i}\otimes [b_{i}, x]\big).\label{eq:comuti}
 \end{eqnarray}
 We say the resulting left Alia bialgebra $(A, [, ], \Delta_{r})$ is {\bf triangular}.

\label{pro:w} Let $(A, [, ])$ be a left Alia algebra and $r=\sum_{i} a_{i}\otimes b_{i}\in A\otimes A$. Then $r$ is a solution of left Alia Yang-Baxter equation in $(A, [, ])$ if and only if
 \begin{eqnarray}
 (\id\otimes \Delta_{r})(r)=\sum_{i, j} -[a_{i}, a_{j}]\otimes b_{i}\otimes b_{j},\label{eq:dra}
 \end{eqnarray}
 where $\Delta_{r}$ is defined by Eq.\eqref{eq:comuti}.

 If further, $r$ is antisymmetric (in the sence of $r+\tau(r)=0$), then $r$ is a solution of left Alia Yang-Baxter equation in $(A, [, ])$ if and only if
 \begin{eqnarray}\label{eq:dr}
 (\Delta_{r}\otimes \id)(r)=\sum_{i, j} a_{i}\otimes a_{j}\otimes [b_{i}, b_{j}],
 \end{eqnarray}
 holds.

\label{pro:ba} Let $((A, [, ]), N)$ be an $S$-adjoint-admissible Nijenhuis left Alia algebra and $r\in A\otimes A$. Define a linear map $\Delta: A\longrightarrow A\otimes A$  by Eq.\eqref{eq:comuti}. Then the following assertions hold.
 \begin{enumerate}[(1)]
   \item\label{it:pro:ba1} Eq.\eqref{eq:nlaca} holds if and only if, for all $x\in A$,
 \begin{eqnarray}
 &&(\mathcal{R}(S(x))-\mathcal{L}(S(x))\otimes \id-S\circ(\mathcal{R}(x)-\mathcal{L}(x))\otimes \id)(N\otimes \id -\id \otimes S)(r)\nonumber\\
 &&\hspace{30mm}+(\id\otimes \mathcal{R}(S(x))-\id\otimes S\circ \mathcal{R}(x))(S\otimes \id-\id\otimes N)(r)=0.\label{eq:41}
 \end{eqnarray}
   \item \label{it:pro:ba2} Eqs.\eqref{eq:laacaadmi1}-\eqref{eq:laacaadmi2} hold if and only if, for all $x\in A$,
 \begin{eqnarray}
 &&\big(\id\otimes (N\circ \mathcal{R}(x)-\mathcal{R}(N(x)))+(\mathcal{R}(N(x))-\mathcal{L}(N(x)))\otimes \id\nonumber\\
 &&\hspace{20mm}+S\circ(\mathcal{R}(x)-\mathcal{L}(x))\otimes \id\big)(S\otimes \id-\id\otimes N)(r)\label{eq:42}\\
 &&\hspace{30mm}+\big((\mathcal{L}(x)-\mathcal{R}(x))\circ S^{2}\otimes \id +(\mathcal{R}(x)-\mathcal{L}(x))\otimes N^{2}\big)(r)=0,\nonumber\\
 &&\big(N\circ (\mathcal{R}(x)-\mathcal{L}(x))\otimes \id- (\mathcal{R}(N(x))-\mathcal{L}(N(x))\otimes \id \nonumber\\
 &&\hspace{20mm}+\id\otimes (\mathcal{R}(N(x))+S\circ \mathcal{R}(x)))\big)(N\otimes \id-\id\otimes S)(r)\label{eq:43}\\
 &&\hspace{60mm}+\big(\id\otimes\mathcal{R}(x)\circ S^{2}-N^{2}\otimes \mathcal{R}(x)\big)(r)=0,\nonumber
 \end{eqnarray}
 \end{enumerate}

\label{eq:bc}
 \begin{enumerate}[(1)] 		
 \item\label{it:eq:bc1}	If $(N\otimes \id -\id \otimes S)(r)=0$, then $(\id\otimes\mathcal{R}(x)\circ S^{2}-N^{2}\otimes \mathcal{R}(x))(r)=0$.
 \item\label{it:eq:bc2}	If $(S\otimes \id-\id\otimes N)(r)=0$, then $((\mathcal{L}(x)-\mathcal{R}(x))\circ S^{2}\otimes \id +(\mathcal{R}(x)-\mathcal{L}(x))\otimes N^{2})(r)=0$.
 \item\label{it:eq:bc3}	If $r$ is antisymmetric, then $(N\otimes \id -\id \otimes S)(r)=0$ if and only if $(S\otimes \id-\id\otimes N)(r)=0$.
 \end{enumerate}

\label{cor:be} Let $((A, [, ]), N)$ be an $S$-adjoint-admissible Nijenhuis left Alia algebra and $r\in A\otimes A$ is antisymmetric. Define a linear map $\Delta$  by Eq.\eqref{eq:comuti}. Then $((A, [, ], \Delta), N, S)$ is a Nijenhuis left Alia bialgebra if Eq.(\ref{eq:ybq}) and the following equation hold:
 \begin{eqnarray}
 (S\otimes \id-\id\otimes N)(r)=0.\label{eq:salaeq2}
 \end{eqnarray}

\label{de:bi}\cite{KLY} Let $(A, [, ])$ be a left Alia algebra with a representation $(V, \ell, r)$. A linear map $T: V\longrightarrow A$ is called a {\bf relative Rota-Baxter operator of $(A, [, ])$ associated to $(V, \ell, r)$} if the following equation holds:
 \begin{equation}
 [T(u), T(v)]=T(\ell(T(u))(v)+r(T(v))(u)), \forall~ u, v\in V. \label{eq:weakr1}
 \end{equation}

\label{lem:bii}{\em \cite{KLY}} Let $(A, [, ])$ be a left Alia algebra and $r\in A\otimes A$ anti-symmetric. Then $r$ is a solution of the left Alia Yang-Baxter equation in $(A, [, ])$ if and only if $r^\#$ defined in Eq.(\ref{eq:rsharp}) is a relative Rota-Baxter operator of $(A, [, ])$ associated to $(A^{*}, \mathcal{L_{A}^{*}},\mathcal{L_{A}^{*}}-\mathcal{R_{A}^{*}})$, i.e.,
 \begin{eqnarray}
 [r^\#(a^{*}), r^\#(b^{*})]=r^\#(\mathcal{L_{A}^{*}}(r^\#(a^{*}))b^{*}+(\mathcal{L_{A}^{*}}
 -\mathcal{R_{A}^{*}})(r^\#(b^{*}))a^{*}), ~\forall~ a^{*}, b^{*}\in A^{*}.\label{eq:54}
 \end{eqnarray}

\label{thm:bj} Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra, $r\in A\otimes A$ antisymmetric and $S: A\longrightarrow A$ a linear map. Then $r$ is a solution of the $S$-admissible left Alia Yang-Baxter equation in $((A, [, ]), N)$ if and only if $r^\#$ is a relative Rota-Baxter operator of $(A, [, ])$ associated to $(A^{*}, \mathcal{L_{A}^{*}}, \mathcal{L_{A}^{*}}-\mathcal{R_{A}^{*}})$ and the equation below holds:
 \begin{eqnarray}\label{eq:bj1}
 N\circ r^\#=r^\#\circ S^{*}.
 \end{eqnarray}

By Lemma \ref{lem:bii}, $r$ is a solution of left Alia Yang-Baxter equation in $(A, [, ])$ if and only if Eq.\eqref{eq:54} holds. Moreover, for all $a^{*}, b^{*}\in A^{*}$, we have
 \begin{eqnarray*}
 &&\langle b^{*}, r^\#(S^{*}(a^{*})) \rangle=\langle S^{*}(a^{*})\otimes b^{*}, r\rangle =\langle a^{*}\otimes b^{*}, (S\otimes \id)(r) \rangle,\\
 &&\langle b^{*}, N(r^\#(a^{*})) \rangle=\langle  N^{*}(b^{*}), r^\#(a^{*}) \rangle =\langle a^{*}\otimes N^{*}(b^{*}), r \rangle=\langle  a^{*}\otimes b^{*}, (\id\otimes N)r \rangle.
 \end{eqnarray*}
 Hence, Eq.\eqref{eq:bj1} if and only if Eq.\eqref{eq:salaeq2} holds.

\label{de:bk} Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra, $(V, \ell, r)$ a representation of $(A, [, ])$ and $\alpha: V\longrightarrow V$ a linear map. A linear map $T: V\longrightarrow A$ is called a {\bf weak relative Rota-Baxter operator of $((A, [, ]), N)$ associated to $(V, \ell, r)$ and $\alpha$} if $T$ is a relative Rota-Baxter operator of $(A, [, ])$ associated to $(V, \ell, r)$ and the equation below holds:
 \begin{eqnarray}
 N\circ T=T\circ \alpha.\label{eq:weakr2}
 \end{eqnarray}
 If $((V, \ell, r), \alpha)$ is a representation of $((A, [, ]), N)$, then $T$ is called a {\bf relative Rota-Baxter operator of $((A, [, ]), N)$ associated to $((V, \ell, r), \alpha)$}.

\label{thm:bn} Let $((A, [, ]), N)$ be a Nijenhuis left Alia algebra, $(V, \ell, r)$ a representation of $(A, [, ])$, $S: A\longrightarrow A$ and $\alpha, \beta: V\longrightarrow V$ linear maps. Then the following conditions are equivalent.
 \begin{enumerate}[(1)]
 \item \label{it:thm:bn1} There is a Nijenhuis left Alia algebra $(A\ltimes_{\ell, r} V, N+\alpha)$ such that the linear map $S+\beta$ on $A\oplus V$ is adjoint-admissible to~ $(A\ltimes_{\ell, r} V, N+\alpha)$.		
 \item \label{it:thm:bn2} There is a Nijenhuis left Alia algebra $(A\ltimes_{\ell^{*}, \ell^{*}-r^{*}} V^{*}, N+\beta^{*})$ such that the linear map $S+\alpha^{*}$ on $A\oplus V^{*}$ is adjoint-admissible to~  $(A\ltimes_{\ell^{*}, \ell^{*}-r^{*}} V^{*}, N+\beta^{*})$.	
 \item \label{it:thm:bn3} The following conditions are satisfied:		
 \begin{enumerate}
 \item \label{it:thm:bna} $((V, \ell, r), \alpha)$ is a representation of $((A, [, ]), N)$, that is, Eqs.\eqref{eq:8} and \eqref{eq:9} hold.		
 \item \label{it:thm:bnb} $S$ is adjoint-admissible to~ $((A, [, ]), N)$,  that is, Eqs.\eqref{eq:15} and \eqref{eq:16} hold.		
 \item \label{it:thm:bnc} $\beta$ is admissible to~ $((A, [,]), N)$ on $(V, \ell, r)$,  that is, Eqs.\eqref{eq:13} and \eqref{eq:14} hold.		
 \item \label{it:thm:bnd} The following equations hold, for all $x\in A$, $v\in V$,
 \begin{eqnarray}
 &\beta(r(x)(\alpha(v)))+r(S^{2}(x))(v)=r(S(x))(\alpha(v))+\beta(r(S(x))(v)),&\label{eq:59}\\
 &\beta(\ell(x)(\alpha(v)))+\ell(S^{2}(x))(v)=\ell(S(x))(\alpha(v))+\beta(\ell(S(x))(v)).&\label{eq:60}
 \end{eqnarray}
 \end{enumerate}
 \end{enumerate}

\label{lem:bm}{\em \cite{KLY}} Let $(A, [, ])$ be a left Alia algebra with a representation  $(V, \ell, r)$. Let $T: V\longrightarrow A$ be a linear map and $T_{\sharp}\in V^{*}\otimes A\subset (A\oplus V^{*})\otimes  (A\oplus V^{*})$ given by
 \begin{equation*}
 \langle T_{\sharp}, u\otimes a^{*}\rangle:=\langle T(u), a^{*}\rangle, \forall~ u\in V, a^{*}\in A^{*}.
 \end{equation*}
 Then $r=T_{\sharp}-\tau(T_{\sharp})$ is an antisymmetric solution of the left Alia Yang-Baxter equation in $A\ltimes_{\ell^{*}, \ell^{*}-r^{*}} V^{*}$ if and only if $T$ is a relative Rota-Baxter operator of $(A, [, ])$ associated to  $(V, \ell, r)$.

\ref{it:thm:bo1} Let $\{e_{1}, e_{2}, ..., e_{n}\}$ be a basis of $V$ and  $\{e_{1}^{*}, e_{2}^{*},..., e_{n}^{*}\}$ be the dual basis. Then
 \begin{eqnarray*}
 &&\hspace{-6mm}T_{\sharp}=\sum_{i} e_{i}^{*}\otimes T(e_{i})\in  V^{*}\otimes A\subset (A\oplus V^{*})\otimes  (A\oplus V^{*}),\\
 &&\hspace{-6mm}r=T_{\sharp}-\tau(T_{\sharp})=\sum_{i} (e_{i}^{*}\otimes T(e_{i})-T(e_{i})\otimes e_{i}^{*}).
 \end{eqnarray*}
 Note that
 \begin{eqnarray*}
 &&\hspace{-6mm}((S+\alpha^{*})\otimes \id)(r)=\sum_{i} (\alpha^{*}(e_{i}^{*})\otimes T(e_{i})-S(T(e_{i}))\otimes e_{i}^{*}),\\
 &&\hspace{-6mm}(\id\otimes(N+\beta^{*}))(r)=\sum_{i} (e_{i}^{*}\otimes N(T(e_{i}))-T(e_{i})\otimes \beta^{*}(e_{i}^{*})).
 \end{eqnarray*}
 Further,
 \begin{eqnarray*}
 &&\hspace{-6mm}\sum_{i} T(e_{i})\otimes \beta^{*}(e_{i}^{*})=\sum_{i} T(\beta(e_{i}))\otimes e_{i}^{*},\\
 &&\hspace{-6mm}\sum_{i} \alpha^{*}(e_{i}^{*})\otimes T(e_{i})=\sum_{i} e_{i}^{*}\otimes T(\alpha(e_{i})).
 \end{eqnarray*}
 Therefore $((S+\alpha^{*})\otimes \id)(r)=(\id\otimes(N+\beta^{*}))(r)$ if and only if $T\circ \beta=S\circ T$ and $N\circ T=T\circ \alpha$. Hence the conclusion follows by Lemma \ref{lem:bm}.
	
 \ref{it:thm:bo2} It follows Item \ref{it:thm:bo1} and Theorem \ref{thm:bn}.

A {\bf commutative and cocommutative associative D-bialgebra} is a triple $(A, \cdot, \delta)$, where the pair $(A, \cdot)$ is a commutative associative algebra, and the pair $(A, \delta)$ is a cocommutative coassociative coalgebra, such that, for all $a, b\in A$,
 \begin{equation}\label{eq:asi}
 \delta(a \cdot b)=a_{[1]}\cdot b\otimes a_{[2]}+b_{[1]}\otimes a\cdot b_{[2]},
 \end{equation}
 where we write $\delta(a)=a_{[1]}\otimes a_{[2]}, \forall~a\in A$.

Since $(A, \cdot, \delta)$ is a commutative cocommutative associative D-bialgebra, we have $\delta(x\cdot y)=\delta(y\cdot x)$, $\forall~x, y\in A$, that is,
 \begin{eqnarray}
 &x_{[1]}\cdot y\otimes x_{[2]}+y_{[1]}\otimes x\cdot y_{[2]}=y_{[1]}\cdot x\otimes y_{[2]}+x_{[1]}\otimes y\cdot x_{[2]}.&\label{eq:asi1}
 \end{eqnarray}
 Next we check that Eq.\eqref{eq:pro:ajj1} holds as follows. 
 {\small \begin{eqnarray*}
 \hbox{LHS of Eq.}\eqref{eq:pro:ajj1}
 \hspace{-3mm}&=&\hspace{-3mm}\underline{f(y)_{[1]}\otimes g(x\cdot f(y)_{[2]})}\underline{-g(x\cdot f(y)_{[2]})\otimes f(y)_{[1]}}+g(x_{[2]})\otimes g(x_{[1]}\cdot y)\\
 &&\hspace{-3mm}-g(x_{[1]}\cdot y)\otimes g(x_{[2]})+f(x)_{[2]}\otimes f(x)_{[1]}\cdot f(y)-f(x)_{[1]}\cdot f(y)\otimes f(x)_{[2]}\\
 &&\hspace{-3mm}\underbrace{+f(x)_{[2]}\otimes g(f(x)_{[1]}\cdot y)}\underbrace{-g(f(x)_{[1]}\cdot y)\otimes f(x)_{[2]}}+\underbrace{g(y\cdot f(x)_{[2]})\otimes f(x)_{[1]}}\\
 &&\hspace{-3mm}\underbrace{-f(x)_{[1]}\otimes g(y\cdot f(x)_{[2]})}-g(y_{[2]})\otimes g(y_{[1]}\cdot x)+g(y_{[1]}\cdot x)\otimes g(y_{[2]})\\
 &&\hspace{-3mm}-f(y)_{[2]}\otimes f(y)_{[1]}\cdot f(x)+f(y)_{[1]}\cdot f(x)\otimes f(y)_{[2]}\underline{-f(y)_{[2]}\otimes g(f(y)_{[1]}\cdot x)}\\
 &&\hspace{-3mm}\underline{+g(f(y)_{[1]}\cdot x)\otimes f(y)_{[2]}}\\
 &=&\hspace{-3mm}\underline{g(x_{[2]})\otimes g(x_{[1]}\cdot y)-g(x_{[1]}\cdot y)\otimes g(x_{[2]})}\\
 &&\hspace{-3mm}\underbrace{+f(x)_{[2]}\otimes f(x)_{[1]}\cdot f(y)-f(x)_{[1]}\cdot f(y)\otimes f(x)_{[2]}}\\
 &&\hspace{-3mm}\underline{-g(y_{[2]})\otimes g(y_{[1]}\cdot x)+g(y_{[1]}\cdot x)\otimes g(y_{[2]})}\\
 &&\hspace{-3mm}\underbrace{-f(y)_{[2]}\otimes f(y)_{[1]}\cdot f(x)+f(y)_{[1]}\cdot f(x)\otimes f(y)_{[2]}}\\
 &\stackrel{\eqref{eq:asi1}}{=}&0,
 \end{eqnarray*}
 }	
 as desired.

\label{de:x} Let $(A, \Delta)$ be a left Alia coalgebra and $\omega\in (A\otimes A)^{*}$ a bilinear from. The equation
 \begin{eqnarray}\label{eq:dybq}
 \omega(x_{(1)}, y)\omega(x_{(2)}, z)+\omega(x, y_{(2)})\omega(y_{(1)}, z)=\omega(x, y_{(1)})\omega(y_{(2)}, z)+\omega(x, z_{(2)})\omega(y, z_{(1)}),
 \end{eqnarray}
 where $x, y, z\in A$, is called a {\bf co-left Alia Yang-Baxter equation} in $(A, \Delta)$.

\label{thm:y} Let $(A, \Delta)$ be a left Alia coalgebra and $\omega\in( A\otimes A)^{*}$. Suppose that $\omega$ is skew-symmetric (in the sense of $\omega(x, y)+\omega(y, x)=0$) solution of the co-left Alia Yang-Baxter equation in $(A, \Delta)$. Then $(A, [, ]_{\omega}, \Delta)$ is a left Alia bialgebra, where $[, ]_{\omega}: A\otimes A\longrightarrow A$ is given by
 \begin{eqnarray}\label{eq:muti}
 [x, y]_{\omega}=x_{(2)}\omega(x_{(1)}, y)-x_{(1)}\omega(x_{(2)}, y)-y_{(2)}\omega(x, y_{(1)}), \forall~ x,y\in A.
 \end{eqnarray} 	
 This bialgebra is called a {\bf dual triangular left Alia bialgebra}.

We only check that the symmetric Jacobi identity holds for $[, ]_{\omega}$ as follows, the rest are straightforward. For all $x, y, z\in A$, we have
 \begin{eqnarray*}
 [x, y]_{\omega}-[x, y]_{\omega}
 \hspace{-3mm}&=&\hspace{-3mm}x_{(2)}\omega(x_{(1)}, y)-x_{(1)}\omega(x_{(2)}, y)-y_{(2)}\omega(x, y_{(1)})-y_{(2)}\omega(y_{(1)}, x)\\
 &&\hspace{-3mm}+y_{(1)}\omega(y_{(2)}, x)+x_{(2)}\omega(y, x_{(1)})\\
 &=&\hspace{-3mm}-x_{(1)}\omega(x_{(2)}, y)+y_{(1)}\omega(y_{(2)}, x).
 \end{eqnarray*}
 So
 \begin{eqnarray*}
 &&\hspace{-15mm}[[x, y]_{\omega}-[x, y]_{\omega}, z]_{\omega}+[[y, z]_{\omega}-[y, z]_{\omega}, x]_{\omega}+	[[z, x]_{\omega}-[x, z]_{\omega}, y]_{\omega}\\ &=&\hspace{-3mm}-\omega(x_{(2)}, y)\omega(x_{(1)(1)}, z)x_{(1)(2)}
 +\omega(x_{(2)}, y)\omega(x_{(1)(2)}, z)x_{(1)(1)}
 +\underline{\omega(x_{(2)}, y)\omega(x_{(1)}, z_{(1)})z_{(2)}}\\
 &&\hspace{-3mm}+\omega(y_{(2)}, x)\omega(y_{(1)(1)}, z)y_{(1)(2)}
 -\omega(y_{(2)}, x)\omega(y_{(1)(2)}, z)y_{(1)(1)}
 -\underline{\omega(y_{(2)}, x)\omega(y_{(1)}, z_{(1)})z_{(2)}}\\
 &&\hspace{-3mm}-\omega(y_{(2)}, z)\omega(y_{(1)(1)}, x)y_{(1)(2)}
 +\omega(y_{(2)}, z)\omega(y_{(1)(2)}, x)y_{(1)(1)}
 +\underbrace{\omega(y_{(2)}, z)\omega(y_{(1)}, x_{(1)})x_{(2)}}\\
 &&\hspace{-3mm}+\omega(z_{(2)}, y)\omega(z_{(1)(1)}, x)z_{(1)(2)}-\omega(z_{(2)}, y)\omega(z_{(1)(2)}, x)z_{(1)(1)}
 -\underbrace{\omega(z_{(2)}, y)\omega(z_{(1)}, x_{(1)})x_{(2)}}\\
 &&\hspace{-3mm}-\omega(z_{(2)}, x)\omega(z_{(1)(1)}, y)z_{(1)(2)}+\omega(z_{(2)}, x)\omega(z_{(1)(2)}, y)z_{(1)(1)}
 +\underleftrightarrow{\omega(z_{(2)}, x)\omega(z_{(1)}, y_{(1)})y_{(2)}}\\
 &&\hspace{-3mm}+\omega(x_{(2)}, z)\omega(x_{(1)(1)}, y)x_{(1)(2)}-\omega(x_{(2)}, z)\omega(x_{(1)(2)}, y)x_{(1)(1)}
 -\underleftrightarrow{\omega(x_{(2)}, z)\omega(x_{(1)}, y_{(1)})y_{(2)}}\\
 &\stackrel{\eqref{eq:dybq}}{=}&\hspace{-3mm}\underbrace{-\omega(x_{(2)}, y)\omega(x_{(1)(1)}, z)x_{(1)(2)}+\omega(x_{(2)}, y)\omega(x_{(1)(2)}, z)x_{(1)(1)}
 -\omega(y, x_{(1)(2)})\omega(x_{(1)(1)}, z)x_{(2)}}\\
 &&\hspace{-3mm}\underleftrightarrow{+\omega(y_{(2)}, x)\omega(y_{(1)(1)}, z)y_{(1)(2)}-\omega(y_{(2)}, x)\omega(y_{(1)(2)}, z)y_{(1)(1)}
 +\omega(z, y_{(1)(1)})\omega(y_{(1)(2)}, z)y_{(2)}}\\
 &&\hspace{-3mm}\underleftrightarrow{-\omega(y_{(2)}, z)\omega(y_{(1)(1)}, x)y_{(1)(2)}+\omega(y_{(2)}, z)\omega(y_{(1)(2)}, x)y_{(1)(1)}
 -\omega(z, y_{(1)(2)})\omega(y_{(1)(1)}, x)y_{(2)}}\\
 &&\hspace{-3mm}\underline{+\omega(z_{(2)}, y)\omega(z_{(1)(1)}, x)z_{(1)(2)}-\omega(z_{(2)}, y)\omega(z_{(1)(2)}, x)z_{(1)(1)}
 -\omega(x, z_{(1)(2)})\omega(z_{(1)(1)}, y)z_{(2)}}\\
 &&\hspace{-3mm}\underline{-\omega(z_{(2)}, x)\omega(z_{(1)(1)}, y)z_{(1)(2)}+\omega(z_{(2)}, x)\omega(z_{(1)(2)}, y)z_{(1)(1)}
 +\omega(x, z_{(1)(1)})\omega(z_{(1)(2)}, y)z_{(2)}}\\
 &&\hspace{-3mm}\underbrace{+\omega(x_{(2)}, z)\omega(x_{(1)(1)}, y)x_{(1)(2)}-\omega(x_{(2)}, z)\omega(x_{(1)(2)}, y)x_{(1)(1)}
 +\omega(y, x_{(1)(1)})\omega(x_{(1)(2)}, z)x_{(2)}}\\
 &\stackrel{\eqref{eq:cola}}{=}&0,
 \end{eqnarray*}
 completing the proof.

\label{pro:z} Let $(A, \Delta)$ be a left Alia coalgebra and $\omega\in( A\otimes A)^{*}$ a bilinear form. Then $\omega$ is a solution of co-left Alia Yang-Baxter equation in $(A, \Delta)$, if and only if
 \begin{eqnarray}\label{eq:mw}
 \omega(x, [y, z]_{\omega})=-\omega(x_{(1)}, y)\omega(x_{(2)}, z),
 \end{eqnarray}
 where $[, ]_{\omega}$ is defined by Eq.\eqref{eq:muti}. 	

 If further $\omega\in( A\otimes A)^{*}$ is skew-symmetric, then $\omega$ is a solution of co-left Alia Yang-Baxter equation in $(A, \Delta)$, if and only if
 \begin{eqnarray}\label{eq:mwr}
 \omega([x, y]_{\omega}, z)=\omega(x, z_{(1)})\omega(y, z_{(2)}),
 \end{eqnarray}
 holds, where $x, y, z\in A$.

\label{de:abb}\cite{KLY} Let $(A, [, ])$ be a left Alia algebra and $\omega\in (A\otimes A)^{*}$ a skew-symmetric element. Assume that
 \begin{eqnarray}\label{eq:symplectic}
 \omega([y, z]-[z, y], x)=\omega([x, y], z)-\omega([x, z], y),\forall~ x, y, z\in A.
 \end{eqnarray}
 then we call $\omega$ a {\bf symplectic structure} on $(A, [, ])$, and $(A, [, ])$ a {\bf symplectic left Alia algebra} denoted by $(A, [, ], \omega)$.

\label{rmk:de:abb} If $r^\#$ defined by Eq.(\ref{eq:rsharp}) is bijective, then we call $r$ {\bf nondegenerate}. By \cite[Proposition 5.4]{KLY}, we know that $r$ is an antisymmetric nondegenerate solution of the left Alia Yang-Baxter equation in $(A, [, ])$ if and only if $\omega_r$ is a nondegenerate symplectic structure on $(A, [, ])$, where $\omega_r$ is defined by
 \begin{eqnarray} 
 \omega_r(x, y):=\langle {r^\#}^{-1}(x), y \rangle.\label{eq:omegar}
 \end{eqnarray}

\label{thm:ac} Let $(A, [, ],\omega)$ be a symplectic left Alia algebra and $r\in A\otimes A$. If $(A, [, ], \Delta_{r})$ is a triangular left Alia bialgebra together with the comultiplication $\Delta_{r}$ given by Eq.\eqref{eq:comuti}, and further $(A, [, ]_{\omega}, \Delta_{r})$ is a dual triangular left Alia bialgebra together with the multiplication $[, ]_{\omega}$ given by Eq.\eqref{eq:muti}, then $((A, [, ]), N)$ is a Nijenhuis left Alia algebra, where $N:A\longrightarrow A$ is given by
 \begin{equation}\label{eq:ac2}
 N(x):=\sum_{i}\omega(x, a_{i})b_{i}, \forall~ x\in A.
 \end{equation}

\label{de:agg}	Let $(A, \Delta)$ be a  left Alia coalgebra and $r \in A\otimes A$ an antisymmetric element. Assume that
 \begin{eqnarray}\label{eq:cosymplectic}
 \sum_i (a_{i(1)}\otimes a_{i(2)}\otimes b_{i}-a_{i(2)}\otimes a_{i(1)}\otimes b_{i}-a_{i(2)}\otimes b_{i}\otimes a_{i(1)}+b_{i}\otimes a_{i(2)}\otimes a_{i(1)})=0.
 \end{eqnarray}
 Then, $(A, \Delta)$ is called a {\bf cosymplectic left Alia coalgebra} denoted by $(A, \Delta, r)$.

\label{thm:aj} Let $(A, \Delta, r)$ be a cosymplectic left Alia coalgebra and $\omega\in (A\otimes A)^{*}$. If $(A, [, ]_{\omega}, \Delta)$ is a dual triangular left Alia bialgebra together with the multiplication $[, ]_{\omega}$ given in Eq.\eqref{eq:muti}, and further $(A, [, ]_{\omega}, \Delta_{r})$ is a triangular left Alia bialgebra together with the comultiplication $\Delta_{r}$ given by Eq.\eqref{eq:comuti}, then $((A, \Delta), S)$ is a Nijenhuis left Alia coalgebra, where $S:A\longrightarrow A$ is given by
 \begin{equation*}
 S(x):=\sum_{i}a_{i}\omega(b_{i}, x), \forall~ x\in A.
 \end{equation*}
